style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.imgur.com/5ZIGTsw.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-color: transparent !important;
  }

  /* Làm trong suốt các khối lớn để thấy nền */
  .container-main,
  .content,
  .navbar,
  .footer-container,
  .games-page,
  .game-card-container {
    background-color: rgba(255, 255, 255, 0.7) !important;
    backdrop-filter: blur(5px) !important;
  }
}
